import{z as l,x as t,o as e,c as d,q as r,j as n,D as B,d as s,s as i,S as o,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"软件供应链安全","description":"","frontmatter":{"title":"软件供应链安全","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ss-supply-chain.md","filePath":"cs/ss-supply-chain.md","lastUpdated":1791063341000}'),p={name:"cs/ss-supply-chain.md"};function c(h,E,u,m,D,F){const A=t("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="软件供应链安全" tabindex="-1">软件供应链安全 <a class="header-anchor" href="#软件供应链安全" aria-label="Permalink to &quot;软件供应链安全&quot;">​</a></h1><div class="epigraph"><p>你审计的是自己的代码，运行的却是几百个陌生人的业余项目；攻击者于是不再撞你的门，改劫你的快递。</p><footer>—— 据 Thompson, Reflections on Trusting Trust, 1984；SolarWinds 与 xz-utils 事件公开报告整理</footer></div><p><a href="/cs/ss-sandbox-escape">上一课</a>回答了「边界内的代码被打穿之后还剩多少」。本课把镜头拉向更早的一环：打进来的代码从哪来。主干已有<a href="/cs/sbom-reproducible-builds">SBOM 与可复现构建</a>、<a href="/cs/dependency-confusion">依赖混淆</a>、<a href="/cs/patch-management">补丁管理</a>与<a href="/cs/firmware-security">固件安全</a>；缺口是把从上游维护者到你的构建产物之间的整条链当成攻防面，钉成一张站点图：攻击者在哪几站下手，每一站的防御对应物是什么。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>现代软件的自研占比很小：一个二进制里，你的代码是少数派，其余来自依赖与构建链。只审计自己的代码守不住面，因为攻击面已经转移：链条上每一站都是一次「别人写的代码在你这里获得执行权」。上游站：维护者账号被社工、被转手、被倦怠出租。构建站：编译器与构建机本身就是代码（Thompson 的 Trusting Trust 证明了编译器可以是永久后门的宿主），构建机被入侵则产物可被替换——SolarWinds 2020 年的入侵正是往更新产物里塞了后门，再借合法签名通道分发给上万客户。分发站：更新通道被劫持，2017 年乌克兰税务软件 M.E.Doc 的更新通道被用来分发 NotPetya，几十小时内席卷全球。消费站：依赖解析骗过 CI，依赖混淆一课已有专述。</p><p><span class="marginnote">供应链攻击的直觉类比：入室盗窃不砸你家门，改在快递中转站把包裹换了——你签收时包裹带着完整的官方封条。SolarWinds 里上万客户收到的更新「签名齐全、通道正规」，坏只在源头那一站；这就是为什么只盯自家门锁（终端防护）守不住，要盯整条快递线。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="站点对防御" tabindex="-1">站点对防御 <a class="header-anchor" href="#站点对防御" aria-label="Permalink to &quot;站点对防御&quot;">​</a></h3><p>每一站配一件防御。上游：维护者身份是软环节，多元维护、关键库供资与交接审计是仅有的对策——技术单点防不住耐心的人。构建：<a href="/cs/sbom-reproducible-builds">可复现构建</a>把「源码加配方到产物」变成任何人可重算的函数，签名从「构建机声称这是产物」变成「配方重算得出同一哈希」；provenance 分级框架把「构建有多可证」变成可比的等级。分发：通道签名校验、密钥硬件化。消费：<a href="/cs/sbom-reproducible-builds">SBOM</a> 回答「我中没中招」，<a href="/cs/patch-management">补丁管理</a>回答「多快修掉」。</p><p><span class="marginnote">xz-utils：攻击者自 2021 年起以「Jia Tan」身份耐心贡献直至共同维护者，2024 年 2 月在 5.6.0/5.6.1 的发行包里放入后门而 git 仓库保持干净；3 月 29 日由 Andres Freund 因 sshd 登录多出约 500 毫秒开销而暴露（CVE-2024-3094）。</span></p><p><span class="marginnote">可复现构建就是「同一份源码加同一份配方，在任何机器上重算都得到逐字节相同的产物」。有了它，「产物有没有被动过手脚」从信任问题变成算术问题：拿公开配方自己重算一遍，哈希相等就干净。xz 后门恰好只存在于发行包、git 仓库干净——正是「看源码」照不出来、必须复算才能照出来的那一类。</span></p>',11)),(e(),n(o,null,{default:B(()=>[i(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%222021%EF%BC%9A%E4%BB%A5%E6%96%B0%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BA%A4%E5%B0%8F%E4%BF%AE%E5%B0%8F%E8%A1%A5%22%5D%20--%3E%20S2%5B%222022%EF%BC%9A%E7%A7%AF%E7%B4%AF%E4%BF%A1%E4%BB%BB%EF%BC%8C%E8%8E%B7%E5%BE%97%E6%8F%90%E4%BA%A4%E6%9D%83%22%5D%0A%20%20S2%20--%3E%20S3%5B%222023%EF%BC%9A%E5%8D%87%E4%B8%BA%E5%85%B1%E5%90%8C%E7%BB%B4%E6%8A%A4%E8%80%85%22%5D%0A%20%20S3%20--%3E%20S4%5B%222024-02%EF%BC%9A%E5%90%8E%E9%97%A8%E8%BF%9B%E5%8F%91%E8%A1%8C%E5%8C%85%EF%BC%8C%E6%BA%90%E7%A0%81%E4%BB%93%E5%BA%93%E4%BF%9D%E6%8C%81%E5%B9%B2%E5%87%80%22%5D%0A%20%20S4%20--%3E%20S5%5B%222024-03-29%EF%BC%9Asshd%20%E5%90%AF%E5%8A%A8%E5%A4%9A%E5%87%BA%E7%BA%A6%20500ms%20%E8%A2%AB%E4%BA%BA%E6%B3%A8%E6%84%8F%E5%88%B0%22%5D%0A%20%20S5%20--%3E%20OUT%5B%22%E6%9A%B4%E9%9C%B2%EF%BC%9A%E4%BA%A7%E7%89%A9%E6%9C%89%E6%AF%92%E8%80%8C%E6%BA%90%E7%A0%81%E5%B9%B2%E5%87%80%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[s(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"这张时间线回答的问题是「攻击如何分步推进」：三年半里每一步单看都像正常贡献。常见误区是「开源等于安全」——xz 是开源项目，代码人人可看，但可审计不等于有人审；后门藏在构建脚本而非主干源码，多数贡献者的视线根本不会落在那里。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[s("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"供应链的本质是信任传递：你信任一个产物，等于信任链上每一站的人与机器。可复现构建改变信任的结构——把「信任每一站」收敛为「验证源码哈希与配方」，可验证性替代可信度。xz 一案把两件事同时钉死：后门藏在构建产物而源码仓库干净，说明「看源码」不够，复现构建正是为这一类准备的；同时它针对 sshd 的符号解析定制、绕开了 fuzzing 的常规覆盖——说明任何单点检测都能被定向绕过，链条安全必须靠纵深，这正是第 2 课沙箱逻辑在时间维度的重演：不指望单墙，指望让攻击链每一段都要单独成功。",-1)),(e(),n(o,null,{default:B(()=>[i(A,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20UP%5B%22%E4%B8%8A%E6%B8%B8%EF%BC%9A%E7%BB%B4%E6%8A%A4%E8%80%85%E4%B8%8E%E4%BB%93%E5%BA%93%22%5D%20--%3E%20BUILD%5B%22%E6%9E%84%E5%BB%BA%EF%BC%9A%E7%BC%96%E8%AF%91%E5%99%A8%E4%B8%8E%E6%9E%84%E5%BB%BA%E6%9C%BA%22%5D%0A%20%20BUILD%20--%3E%20DIST%5B%22%E5%88%86%E5%8F%91%EF%BC%9A%E6%9B%B4%E6%96%B0%E9%80%9A%E9%81%93%E4%B8%8E%E9%95%9C%E5%83%8F%22%5D%0A%20%20DIST%20--%3E%20USE%5B%22%E6%B6%88%E8%B4%B9%EF%BC%9A%E4%BE%9D%E8%B5%96%E8%A7%A3%E6%9E%90%E4%B8%8E%E9%83%A8%E7%BD%B2%22%5D%0A%20%20DEFUP%5B%22%E4%B8%8A%E6%B8%B8%E9%98%B2%E5%BE%A1%EF%BC%9A%E8%BA%AB%E4%BB%BD%E5%AE%A1%E8%AE%A1%E4%B8%8E%E4%BE%9B%E8%B5%84%22%5D%20--%3E%20UP%0A%20%20DEFB%5B%22%E6%9E%84%E5%BB%BA%E9%98%B2%E5%BE%A1%EF%BC%9A%E5%8F%AF%E5%A4%8D%E7%8E%B0%E6%9E%84%E5%BB%BA%E4%B8%8E%20provenance%22%5D%20--%3E%20BUILD%0A%20%20DEFD%5B%22%E5%88%86%E5%8F%91%E9%98%B2%E5%BE%A1%EF%BC%9A%E9%80%9A%E9%81%93%E7%AD%BE%E5%90%8D%22%5D%20--%3E%20DIST%0A%20%20DEFU%5B%22%E6%B6%88%E8%B4%B9%E9%98%B2%E5%BE%A1%EF%BC%9ASBOM%20%E4%B8%8E%E8%A1%A5%E4%B8%81%E7%AA%97%E5%8F%A3%22%5D%20--%3E%20USE%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[s(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>依赖混淆的消费端机制专课已讲，本课不重写；固件层的供应链（固件签名、启动链）留给硬件一课的信任传递；合规框架清单（SLSA 等级如何逐条落地）不展开成手册。供应链攻防的攻方细节不写配方，只写结构与案例事实。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>攻击面已从你的代码转移到依赖与构建链；链条上每一站都是一次执行权交接。</li><li>四站四防：上游身份审计、构建可复现加 provenance、分发通道签名、消费 SBOM 与补丁窗口。</li><li>信任传递可被可复现构建收敛：从信任每一站的人，收敛为验证哈希与配方。</li><li>xz 证明后门可藏在产物与维护者身份里，单点检测可被定向绕过，纵深不可省。</li><li>出处：Thompson, 1984；SolarWinds 与 xz 公开报告；对照 <a href="/cs/sbom-reproducible-builds">sbom-reproducible-builds</a>、<a href="/cs/dependency-confusion">dependency-confusion</a>。</li></ul>',4))])}const S=l(p,[["render",c]]);export{C as __pageData,S as default};
